UPDATE WORKLOAD w
LEFT JOIN WORKLOAD own
  ON own.teacher_name = #{currentTeacherName}
 AND own.semester_id = w.semester_id
 AND own.notification_no = w.notification_no
 AND own.course_no = w.course_no
SET w.actual_hours = #{actualHours}
WHERE w.wl_id = #{wlId}
  AND COALESCE(w.confirm_status, 0) = 0
  AND (
      w.teacher_name = #{currentTeacherName}
      OR (w.notification_no IS NOT NULL AND TRIM(w.notification_no) != '' AND own.wl_id IS NOT NULL)
  )

UPDATE WORKLOAD w
LEFT JOIN WORKLOAD own
  ON own.teacher_name = #{currentTeacherName}
 AND own.semester_id = w.semester_id
 AND own.notification_no = w.notification_no
 AND own.course_no = w.course_no
SET w.confirm_status = 1
WHERE w.wl_id = #{wlId}
  AND COALESCE(w.confirm_status, 0) = 0
  AND (
      w.teacher_name = #{currentTeacherName}
      OR (w.notification_no IS NOT NULL AND TRIM(w.notification_no) != '' AND own.wl_id IS NOT NULL)
  )

