SELECT teacher_no, teacher_name, COUNT(*) AS total_records, SUM(CASE WHEN COALESCE(confirm_status, 0) = 1 THEN 1 ELSE 0 END) AS confirmed_records FROM WORKLOAD
semester_id = #{semesterId}
GROUP BY teacher_no, teacher_name ORDER BY teacher_name, teacher_no
